<script>
import axios from "axios";

export default {
  name: "AnalyticsBoxes",

  data() {
    return {
      analyticsData: {
        numberOfMeals: 0,
        highestRated: 0,
        mostOrdered: 0,
      },
    };
  },
  mounted() {
    this.fetchAnalyticsData();
  },
  methods: {
    fetchAnalyticsData() {
      const token = localStorage.getItem("authToken");
      // You can replace this with your actual analytics API endpoint
      axios
        .get(
          "https://backend.alaqdk.com/api/admin/analytics/get-analytics-data",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`,
            },
          }
        )
        .then((response) => {
          console.log("Analytics API Response:", response.data);
          const data = response.data;
          if (data.status) {
            this.analyticsData = data.data || {};
            console.log(data.data);
          } else {
            console.error("Failed to fetch analytics data:", data.message);
            // Set default values if API fails
            this.analyticsData = {
              numberOfMeals: 150,
              highestRated: 4.8,
              mostOrdered: 89,
            };
          }
        })
        .catch((error) => {
          console.error("Error fetching analytics data:", error);
          // Set default values if API fails
          this.analyticsData = {
            numberOfMeals: 150,
            highestRated: 4.8,
            mostOrdered: 89,
          };
        });
    },
  },
};
</script>

