</template>

<script>
import { useToast } from "vue-toastification";
import axios from "axios";

export default {
  props: {
    type: { type: String, required: true },
    row: { type: Object, required: true },
  },
  setup() {
    const toast = useToast();
    return { toast };
  },
  data() {
    return {
      formData: {},
      errors: {},
      isSubmitting: false,
      isDeleting: false,
    };
  },

  computed: {
    filteredFormData() {
      // Exclude id field, lastPurchase field, productCount, and orderCount from form display and API requests
      const formDataWithoutId = { ...this.formData };
      delete formDataWithoutId.id;
      delete formDataWithoutId.lastPurchase;
      delete formDataWithoutId.productCount;
      delete formDataWithoutId.orderCount;
      return formDataWithoutId;
    }
  },

  watch: {
    row: {
      immediate: true,
      handler(newRow) {
        // Initialize formData for 'add' and 'edit' popups
        this.formData =
          this.type === "add" ? this.getEmptyFormData() : { ...newRow };
      },
    },
  },
  methods: {
    validateForm() {
      this.errors = {};
      let isValid = true;

      if (!this.formData.restName?.trim()) {
        this.errors.restName = this.$t("fieldRequired");
        isValid = false;
      }

      // Email validation
      if (this.formData.email && !this.isValidEmail(this.formData.email)) {
        this.errors.email = this.$t("invalidEmail");
        isValid = false;
      }

      // Phone validation
      if (this.formData.phone && !this.isValidPhone(this.formData.phone)) {
        this.errors.phone = this.$t("invalidPhone");
        isValid = false;
      }



      return isValid;
    },
    getEmptyFormData() {
      return {
        restName: "",
        email: "",
        phone: "",
      };
    },
    isValidEmail(email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(email);
    },
    isValidPhone(phone) {
      // Allow various phone formats including international
      const phoneRegex = /^[+]?[1-9][\d]{0,15}$/;
      return phoneRegex.test(phone.replace(/[\s\-()]/g, ''));
    },
    validateField(field) {
      if (field === "restName" && !this.formData.restName?.trim()) {
        this.errors.restName = this.$t("fieldRequired");
      } else if (field === "email" && this.formData.email && !this.isValidEmail(this.formData.email)) {
        this.errors.email = this.$t("invalidEmail");
      } else if (field === "phone" && this.formData.phone && !this.isValidPhone(this.formData.phone)) {
        this.errors.phone = this.$t("invalidPhone");
      } else {
        delete this.errors[field];
      }
    },
    async submitForm() {
      if (!this.validateForm()) {
        this.toast.error(this.$t("formValidationError"));
        return;
      }

      this.isSubmitting = true;

      try {
        const token = localStorage.getItem("authToken");
        const headers = {
          "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
          Authorization: `Bearer ${token}`,
        };

        if (this.type === "edit") {
          // Update existing restaurant
          console.log("Sending edit request with data:", {
            name: this.formData.restName,
            email: this.formData.email,
            phone: this.formData.phone,
          });
          
          // Try different data formats that the backend might expect
          const requestData = {
            name: this.formData.restName,
            email: this.formData.email,
            phone: this.formData.phone,
          };
          
          // Alternative data format - try with different field names
          const alternativeData = {
            restaurant_name: this.formData.restName,
            email: this.formData.email,
            phone: this.formData.phone,
          };
          
          console.log("Request data being sent:", requestData);
          console.log("Alternative data format:", alternativeData);
          
          // Try PUT first, if it fails, try PATCH
          let response;
          try {
            response = await axios.put(
              `https://backend.alaqdk.com/api/admin/restaurants/${this.formData.id}`,
              requestData,
              { headers }
            );
          } catch (putError) {
            console.log("PUT failed, trying PATCH:", putError.response?.status);
            try {
              response = await axios.patch(
                `https://backend.alaqdk.com/api/admin/restaurants/${this.formData.id}`,
                requestData,
                { headers }
              );
            } catch (patchError) {
              console.log("PATCH failed, trying with alternative data format:", patchError.response?.status);
              response = await axios.put(
                `https://backend.alaqdk.com/api/admin/restaurants/${this.formData.id}`,
                alternativeData,
                { headers }
              );
            }
          }

          console.log("Edit response:", response.data);

          if (response.data.status) {
            this.toast.success(this.$t("restaurantUpdated"));
            
            // Verify the update by fetching the updated data
            try {
              const verifyResponse = await axios.get(
                `https://backend.alaqdk.com/api/admin/restaurants/${this.formData.id}`,
                { headers }
              );
              console.log("Verification response:", verifyResponse.data);
            } catch (verifyError) {
              console.error("Verification failed:", verifyError);
            }
            
            this.$emit("save", { ...this.formData });
          } else {
            this.toast.error(response.data.message || this.$t("updateError"));
          }
        } else if (this.type === "add") {
          // Create new restaurant - API might not support this operation
          try {
            const response = await axios.post(
              "https://backend.alaqdk.com/api/admin/restaurants",
              {
                name: this.formData.restName,
                email: this.formData.email,
                phone: this.formData.phone,
              },
              { headers }
            );

            if (response.data.status) {
              this.toast.success(this.$t("restaurantAdded"));
              // Add the ID from the response to the form data
              const newRestaurant = { ...this.formData, id: response.data.data.id };
              this.$emit("save", newRestaurant);
            } else {
              this.toast.error(response.data.message || this.$t("addError"));
            }
          } catch (error) {
            if (error.response && error.response.status === 405) {
              // Method not allowed - restaurant creation might not be supported
              this.toast.error(this.$t("restaurantCreationNotSupported"));
            } else {
              this.toast.error(error.response?.data?.message || this.$t("addError"));
            }
          }
        }
      } catch (error) {
        console.error("API Error:", error);
        console.error("Error response:", error.response?.data);
        console.error("Error status:", error.response?.status);
        this.toast.error(error.response?.data?.message || this.$t("saveError"));
      } finally {
        this.isSubmitting = false;
      }
    },
    async confirmDelete() {
      this.isDeleting = true;

      try {
        const token = localStorage.getItem("authToken");
        const headers = {
          "Accept-Language": this.$i18n.locale === 'ar' ? 'ar' : 'en',
          Authorization: `Bearer ${token}`,
        };

        const response = await axios.delete(
          `https://backend.alaqdk.com/api/admin/restaurants/${this.formData.id}`,
          { headers }
        );

        if (response.data.status) {
          this.toast.success(this.$t("deleteSuccessMessage"));
          this.$emit("save", { ...this.formData }); // Emit a copy of the row for deletion
        } else {
          this.toast.error(response.data.message || this.$t("deleteError"));
        }
      } catch (error) {
        console.error("Delete Error:", error);
        this.toast.error(error.response?.data?.message || this.$t("deleteError"));
      } finally {
        this.isDeleting = false;
      }
    },
  },
};
</script>

<style scoped>
