    font-size: 16px;
  }

  .popup-actions {
    gap: 8px;
    margin: 15px 0;
  }

  .popup-actionsDelete .btns {
    flex-direction: column;
    align-items: center;
    gap: 8px;
  }

  .input-container {
    margin: 8px 0;
  }

  input,
  select,
  textarea {
    width: 100%;
  }

  .semi-header {
    margin: 0 10px;
  }

  .close-btn {
    margin: 0 10px;
    font-size: 20px;
    padding: 8px;
  }

  .popup-actionsDelete p,
  .popup-actionsDelete span {
    width: 100%;
    padding: 0 10px;
    font-size: 14px;
  }
}

/* Extra small devices (phones, 600px and down) */
@media (max-width: 600px) {
  .popup-actions button,
  .popup-actionsDelete .btns button {
    max-width: 100%;
    min-height: 44px;
    font-size: 15px;
  }

  .close-btn {
    font-size: 18px;
  }
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: #f8f5f7;
  border-top-left-radius: 30px;
  border-top-right-radius: 30px;
